using System.Text.Json.Nodes;
using Ombra.Core.Interop;

namespace Ombra.Core.Interop.Tests;

/// <summary>
/// Cross-language test vectors (SERVER_DESIGN §7, §9 row S1) from <c>native/ombra-core/vectors/*.json</c>,
/// generated by <c>gen-vectors</c>. Each case sends <c>{"op": op, ...input}</c> to the stateless ABI:
/// with <c>expect</c> the response is ok and every expected key deep-equals <c>result</c>; with
/// <c>error</c> the response is <c>ok: false</c> with exactly that code.
/// </summary>
public sealed class VectorTests
{
    private static string Dir => Path.Combine(AppContext.BaseDirectory, "vectors");

    private static JsonArray CasesOf(string file) =>
        JsonNode.Parse(File.ReadAllText(Path.Combine(Dir, file)))!["cases"]!.AsArray();

    public static TheoryData<string, string> Cases()
    {
        var data = new TheoryData<string, string>();
        foreach (var path in Directory.GetFiles(Dir, "*.json").Order(StringComparer.Ordinal))
        {
            var file = Path.GetFileName(path);
            foreach (var c in CasesOf(file)) data.Add(file, c!["name"]!.GetValue<string>());
        }
        return data;
    }

    [Theory]
    [MemberData(nameof(Cases))]
    public void Vector(string file, string name)
    {
        var c = CasesOf(file).Single(x => x!["name"]!.GetValue<string>() == name)!.AsObject();
        var input = c["input"]!.AsObject();
        Assert.False(input.ContainsKey("op"), "input must not use the reserved key 'op'");
        var r = OmbraPublic.CallRaw(c["op"]!.GetValue<string>(), input);
        if (c["expect"] is JsonObject expect)
        {
            Assert.Null(c["error"]);
            Assert.True(r["ok"]?.GetValue<bool>() == true, $"expected ok, got {r.ToJsonString()}");
            var result = r["result"]!.AsObject();
            foreach (var (k, v) in expect)
                Assert.True(result.ContainsKey(k) && JsonNode.DeepEquals(result[k], v),
                    $"result.{k} = {result[k]?.ToJsonString()}, expected {v?.ToJsonString()}");
        }
        else
        {
            var code = c["error"]!.GetValue<string>();
            Assert.True(r["ok"]?.GetValue<bool>() == false, $"expected error {code}, got {r.ToJsonString()}");
            Assert.Equal(code, r["code"]?.GetValue<string>());
        }
    }

    [Fact]
    public void Canonical_vectors_cover_bind_heartbeat_and_item_op()
    {
        var ops = CasesOf("canonical.json").Select(c => c!["op"]!.GetValue<string>()).ToHashSet();
        Assert.Contains("invite.bind", ops);
        Assert.Contains("heartbeat.canonical", ops);
        Assert.Contains("itemop.canonical", ops);
    }

    [Fact]
    public void Case_names_are_unique_and_every_file_has_cases()
    {
        var names = new HashSet<string>();
        foreach (var path in Directory.GetFiles(Dir, "*.json"))
        {
            var cases = CasesOf(Path.GetFileName(path));
            Assert.NotEmpty(cases);
            foreach (var c in cases) Assert.True(names.Add(c!["name"]!.GetValue<string>()), $"duplicate case {c["name"]}");
        }
        Assert.True(names.Count > 0);
    }
}
